import { afterEach, beforeEach, describe, it, test } from "node:test";

const globals = globalThis as typeof globalThis & {
  afterEach?: typeof afterEach;
  beforeEach?: typeof beforeEach;
  describe?: typeof describe;
  it?: typeof it;
  test?: typeof test;
};

globals.afterEach ??= afterEach;
globals.beforeEach ??= beforeEach;
globals.describe ??= describe;
globals.it ??= it;
globals.test ??= test;

import assert from "node:assert/strict";
import { ArchitectureScorer } from "../src/architecture/ArchitectureScorer.js";

describe("architecture scorer", () => {
  it("scores candidates", () => {
    const scored = new ArchitectureScorer().score([
      { name: "Monolith", rationale: "Simple", complexity: "small" },
      { name: "Modular Monolith", rationale: "Balanced", complexity: "medium" },
    ]);

    assert.equal(scored[0].name, "Monolith");
    assert.equal(scored[1].name, "Modular Monolith");
  });
});

export interface ScoredArchitecture {
  name: string;
  score: number;
  rationale: string;
}

export class ArchitectureScorer {
  score(candidates: Array<{ name: string; rationale: string; complexity: string }>): ScoredArchitecture[] {
    return candidates.map((candidate) => ({
      name: candidate.name,
      score: candidate.complexity === "large" ? 0.9 : candidate.complexity === "medium" ? 0.8 : 0.7,
      rationale: candidate.rationale,
    }));
  }
}
